// The Opus round-4 redaction corpus (scratchpad m4/redact4.ts), ported verbatim: [label, text]. The secret marker
// S (or the needle chosen per case in NEEDLE) must never survive.
export const S = "Zq9vXk2mWp7rT4ny"; // 16-char secret marker
export const M4: Array<[string, string]> = [
  ["pgp private block", `echo '-----BEG${""}IN PGP PRIVATE KEY BLOCK-----\nlQOYBF${S}\n-----END PGP PRIVATE KEY BLOCK-----'`],
  ["putty ppk", `PuTTY-User-Key-File-3: ssh-ed25519\nPrivate-Lines: 1\nAAAAI${S}`],
  ["aws secret spaced", `aws configure set aws_secret_access_key wJalrXUtnFEMI/K7MDENG/${S}EXAMPLEKEY`],
  ["aws secret yaml", `aws_secret_access_key = wJalrXUtnFEMI/K7MDENG/${S}`],
  ["libpq password short", `psql "host=db user=app password=${S.slice(0,9)}"`],
  ["password= short", `-d "password=${S.slice(0,10)}"`],
  ["yaml pw short", `password: ${S.slice(0,10)}`],
  ["toml pw unquoted short", `password = ${S.slice(0,10)}`],
  ["redis-cli -a", `redis-cli -h h -a ${S}`],
  ["docker login -p", `docker login -u alex -p ${S} ghcr.io`],
  ["mongo -p", `mongosh -u admin -p ${S} host`],
  ["sqlcmd -P", `sqlcmd -S x -U sa -P ${S}`],
  ["ldapsearch -w", `ldapsearch -x -D cn=admin -w ${S}`],
  ["htpasswd -b", `htpasswd -b .htpasswd alex ${S}`],
  ["smbclient %", `smbclient //h/s -U alex%${S}`],
  ["openssl -k", `openssl enc -aes256 -k ${S} -in f`],
  ["zip -P", `zip -P ${S} out.zip f`],
  ["7z -p", `7z a -p${S} out.7z f`],
  ["gpg --passphrase", `gpg --batch --passphrase ${S} -d f.gpg`],
  ["ssh-keygen -N", `ssh-keygen -t ed25519 -N '${S}' -f k`],
  ["keytool -storepass", `keytool -list -keystore k.jks -storepass ${S}`],
  ["java keyStorePassword", `java -Djavax.net.ssl.keyStorePassword=${S} -jar x`],
  ["camel dbPassword", `dbPassword=${S}`],
  ["camel clientSecret", `clientSecret=${S}`],
  ["--db-password", `app --db-password ${S}`],
  ["--http-password", `wget --http-password=${S} url`],
  ["curl --proxy-user", `curl --proxy-user alex:${S} x`],
  ["curl -U", `curl -U alex:${S} x`],
  ["netrc", `machine api.x.com login alex password ${S}`],
  ["gh secret --body", `gh secret set FOO --body "${S}"`],
  ["kubectl literal short", `kubectl create secret generic x --from-literal=db-pass=${S.slice(0,8)}`],
  ["docker auth json", `{"auths":{"ghcr.io":{"auth":"YWxleDp${S}"}}}`],
  ["kube client-key-data", `client-key-data: LS0tLS1CRUdJTi${S}`],
  ["make :=", `DB_PASSWORD := ${S}`],
  ["SECRET_KEY_BASE nonhex", `SECRET_KEY_BASE=${S}${S}`],
  ["SESSION_SECRET_V2", `SESSION_SECRET_V2=${S}`],
  ["sudo -S echo", `echo '${S}' | sudo -S rm x`],
  ["pgpass line", `echo 'db:5432:app:alex:${S}' >> ~/.pgpass`],
  ["discord webhook", `curl https://di${""}scord.com/api/webhooks/1234567890/${S}${S}abcdEFGH`],
  ["groq gsk_", `echo gsk_${S}${S}${S}`],
  ["replicate r8_", `echo r8_${S}${S}abcdefgh`],
  ["perplexity pplx-", `echo pplx-${S}${S}${S}`],
  ["supabase sbp_", `echo sb${""}p_0123456789abcdef0123456789abcdef01234567`],
  ["mailgun key-", `echo ke${""}y-0123456789abcdef0123456789abcdef`],
  ["bitbucket ATBB", `echo ATBB${S}${S}`],
  ["notion ntn_", `echo ntn_${S}${S}${S}`],
  ["airtable pat", `echo pat${S.slice(0,14)}.0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef`],
  ["figma figd_", `echo figd_${S}${S}`],
  ["postman PMAK", `echo PM${""}AK-0123456789abcdef01234567-${S}${S}`],
  ["heroku HRKU", `echo HRKU-${S}${S}`],
  ["square EAAA", `echo EAAA${S}${S}${S}${S}`],
  ["grafana glsa", `echo glsa_${S}${S}_abcdef01`],
  ["twilio SK", `echo SK${""}0123456789abcdef0123456789abcdef`],
  ["lower hex secret", `signing = 0123456789abcdef0123456789abcdef`],
  ["fullwidth equals", `PASSWORD＝${S}`],
  ["nbsp before =", `API_TOKEN =${S}`],
  ["pw in json nested esc", `{\\"password\\":\\"${S}\\"}`],
  ["Authorization lower", `authorization: bearer ${S}`],
  ["x-api-key lower quoted", `-H "x-api-key: ${S}"`],
  ["export spaced sp", `export OPENAI_API_KEY=" ${S}"`],
];

/** The part of a case that must not appear after redaction (m4/redact4.ts's rule). */
export function needleOf(label: string, text: string): string {
  return /PGP|PuTTY/.test(label) ? S : (text.match(/Zq9v\w{0,5}|0123456789abcdef0123|YWxleDp|LS0tLS1C|wJalrX/)?.[0] ?? S);
}
